const item = $input.first().json.result.item;
const file = item.ufCrm12SourceDoc;
const fileObj = Array.isArray(file) ? file[0] : file;
const url = fileObj.urlMachine || fileObj.url || fileObj.downloadUrl;
return [{ json: { itemId: item.id, fileUrl: url, stageId: item.stageId } }];

const inp = $input.first();
const headers = inp.json?.headers || {};
let contentType = (headers['content-type'] || headers['Content-Type'] || '').toLowerCase();
let disposition = headers['content-disposition'] || headers['Content-Disposition'] || '';
let fileName = 'file';
const m = disposition.match(/filename\*?=(?:UTF-8'')?"?([^";]+)"?/i);
if (m) fileName = decodeURIComponent(m[1]);
let format = 'other';
let mimeType = 'application/octet-stream';
if (contentType.startsWith('image/')) {
  format = 'image';
  mimeType = contentType.split(';')[0];
} else if (contentType.includes('pdf')) {
  format = 'pdf';
  mimeType = 'application/pdf';
} else if (contentType.includes('wordprocessingml') || contentType.includes('msword') || fileName.toLowerCase().endsWith('.docx') || fileName.toLowerCase().endsWith('.doc')) {
  format = 'docx';
  mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
} else {
  const bin = inp.binary?.data;
  if (bin && bin.data) {
    const first4 = Buffer.from(bin.data, 'base64').slice(0, 4).toString('hex');
    if (first4.startsWith('89504e47')) { format = 'image'; mimeType = 'image/png'; }
    else if (first4.startsWith('ffd8ff')) { format = 'image'; mimeType = 'image/jpeg'; }
    else if (first4.startsWith('25504446')) { format = 'pdf'; mimeType = 'application/pdf'; }
    else if (first4.startsWith('504b0304')) { format = 'docx'; mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'; }
  }
}
const itemId = $('Extract File URL').first().json.itemId;
return [{ json: { itemId, format, mimeType, fileName }, binary: inp.binary }];

const inp = $input.first();
const binary = inp.binary?.data;
if (!binary) throw new Error('Missing binary data in Build AI Content');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const detected = $('Detect Format').first().json;
const { itemId, format, fileName } = detected;

let contentParts;
if (format === 'image') {
  const b64 = buffer.toString('base64');
  contentParts = [{ type: 'image_url', image_url: { url: `data:${detected.mimeType};base64,${b64}`, detail: 'high' } }];
} else {
  // PDF or DOCX-converted-to-PDF — render at 200 DPI via pdf2png
  let renderResp;
  try {
    renderResp = await this.helpers.httpRequest({
      method: 'POST', url: 'http://pdf2png:5000/pdf-to-images',
      body: JSON.stringify({ pdf_base64: buffer.toString('base64'), dpi: 200, format: 'JPEG', quality: 85 }),
      headers: { 'Content-Type': 'application/json' }, json: false, timeout: 180000
    });
  } catch (e) {
    throw new Error('pdf2png service failed: ' + e.message);
  }
  const parsed = typeof renderResp === 'string' ? JSON.parse(renderResp) : renderResp;
  const pages = parsed.pages || [];
  if (pages.length === 0) throw new Error('pdf2png returned no pages');
  contentParts = pages.map(p => ({ type: 'image_url', image_url: { url: p.data_url, detail: 'high' } }));
}

const systemPrompt = "You extract structured data from vendor/supplier quotation PDFs. The documents come from a construction/architectural firm (TFS Consultants). Extract each quotation's metadata + line items. Output ONLY valid JSON, no markdown. Missing text → empty string; missing numbers → 0. Dates as YYYY-MM-DD (parse '4th November 2025' → '2025-11-04'). Currency values as plain numbers.";

const userText = `Extract the following from this quotation document:

REQUIRED FIELDS:
- reference: The document reference number (e.g. 'TFS / PRJ / 0176 / 11 / 2025/R1' or 'TFS/PRJ/0092/05/2026'). Copy VERBATIM including all slashes, dashes, dots, revision markers (R1, R2, R3). Look for 'Our Ref:' label.
- quotation_date: Date on the quotation (YYYY-MM-DD). Look for 'Date:' label.
- company_name: The recipient company name (customer). It's the company at the top of the letter, right after the ref+date section, before 'Attn:' or the address.
- attn: The specific contact person's name after 'Attn:' or 'Kindly Attention:' label.
- subject: The 'RE:' line describing what the quotation is for.
- validity: The validity period stated (e.g. '45 days', '30 days').
- confirmation: How order confirmation happens (e.g. 'Upon receiving your Purchase Order and Deposit Payment').
- delivery: The delivery period (e.g. '120 working days upon date of confirmation').
- payment_schedule: Full breakdown of payment stages (concatenate as text, e.g. '50% deposit upon confirmation, 40% upon prefabrication/before delivery, 10% balance on completion').
- timeline_start: Estimated project start date (YYYY-MM-DD) if stated, else empty.
- timeline_end: Estimated project end date (YYYY-MM-DD) if stated, else empty.
- line_items: Array of line items from the pricing table. Each with:
    - line_no: sequential number (1, 2, 3...)
    - product_family: base product category (e.g. 'PVDF Membrane Structure', 'HDPE Shade Sail', 'PE Calculation')
    - product_variant_name: full descriptive text as shown in the quotation
    - unit_price_rm: unit price in RM (number, no comma)
    - quantity: quantity (default 1)
    - unit_measure: 'unit', 'lot', 'sqm', etc.
    - line_total_rm: line total

Output schema:
{
  "reference": string,
  "quotation_date": string,
  "company_name": string,
  "attn": string,
  "subject": string,
  "validity": string,
  "confirmation": string,
  "delivery": string,
  "payment_schedule": string,
  "timeline_start": string,
  "timeline_end": string,
  "line_items": [{ "line_no": number, "product_family": string, "product_variant_name": string, "unit_price_rm": number, "quantity": number, "unit_measure": string, "line_total_rm": number }]
}`;

const aiBody = {
  model: 'gpt-5.5',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: [ { type: 'text', text: userText }, ...contentParts ] }
  ],
  max_completion_tokens: 8000,
  response_format: { type: 'json_object' }
};
return [{ json: { itemId, format, fileName, aiBody } }];

// Persist to Bitrix — OCR Doc Extraction, SPA 1046. 1 doc = 1 SPA record (no need multi-quotation splitting like Project 3).
const BASE = $env.BITRIX_TFSSB_URL;
const SPA_ENTITY_TYPE_ID = 1046;
const SPA_CATEGORY_ID = 20;
const PRODUCTROW_OWNER_TYPE = 'T416'; // SYMBOL_CODE_SHORT for entityTypeId 1046
const PROP_PARENT_LINK = 46; // CML2_LINK on iblock 16 (SKU offers)

async function bx(method, body) {
  const r = await this.helpers.httpRequest({
    method: 'POST', url: `${BASE}/${method}`,
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify(body || {}), json: false
  });
  return typeof r === 'string' ? JSON.parse(r) : r;
}

// Parse AI
const resp = $input.first().json;
const raw = resp.choices?.[0]?.message?.content;
if (!raw) throw new Error('OpenAI returned no content');
let data;
try { data = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch (e) { throw new Error('AI JSON parse failed: ' + String(raw).slice(0, 300)); }

const origItemId = $('Detect Format').first().json.itemId;

// Idempotency: delete existing product rows on this SPA item
for (let attempt = 0; attempt < 4; attempt++) {
  const existing = await bx.call(this, 'crm.item.productrow.list', { filter: { '=ownerType': PRODUCTROW_OWNER_TYPE, '=ownerId': origItemId } });
  const rows = existing.result?.productRows || [];
  if (rows.length === 0) break;
  for (const row of rows) {
    await bx.call(this, 'crm.item.productrow.delete', { id: row.id });
  }
}

// 1. Update SPA item with quotation metadata
const quoteFields = {
  ufCrm12Reference: data.reference || '',
  ufCrm12QuotationDate: data.quotation_date || null,
  ufCrm12CompanyName: data.company_name || '',
  ufCrm12Attn: data.attn || '',
  ufCrm12Subject: data.subject || '',
  ufCrm12Validity: data.validity || '',
  ufCrm12Confirmation: data.confirmation || '',
  ufCrm12Delivery: data.delivery || '',
  ufCrm12PaymentSchedule: data.payment_schedule || '',
  ufCrm12TimelineStart: data.timeline_start || null,
  ufCrm12TimelineEnd: data.timeline_end || null
};
// Also set title to reference for easier UI browsing
const spaTitle = data.reference
  ? `${data.reference}${data.company_name ? ' — ' + data.company_name : ''}`
  : `OCR Doc ${origItemId}`;
await bx.call(this, 'crm.item.update', {
  entityTypeId: SPA_ENTITY_TYPE_ID, id: origItemId,
  fields: { ...quoteFields, title: spaTitle }
});

// 2. For each line item — find/create parent+SKU in catalog, then add productrow
const lines = data.line_items || [];
const results = [];
for (const li of lines) {
  const productFamily = String(li.product_family || 'Unnamed').trim().slice(0, 250);
  const productVariantName = String(li.product_variant_name || li.product_family || 'Line Item').trim().slice(0, 250);
  const unitPrice = li.unit_price_rm || 0;
  const quantity = li.quantity || 1;

  // Find/create parent (iblock 14)
  let parentId;
  const parentFind = await bx.call(this, 'catalog.product.list', {
    select: ['id','name','iblockId'],
    filter: { iblockId: 14, '=name': productFamily }
  });
  const parentMatches = parentFind.result?.products || [];
  if (parentMatches.length > 0) {
    parentId = parentMatches[0].id;
  } else {
    const parentAdd = await bx.call(this, 'catalog.product.add', {
      fields: { iblockId: 14, name: productFamily, active: 'Y' }
    });
    parentId = parentAdd.result?.element?.id;
    if (!parentId) throw new Error('Parent create failed: ' + JSON.stringify(parentAdd));
  }

  // Find/create SKU (iblock 16)
  let skuId;
  const skuFind = await bx.call(this, 'catalog.product.list', {
    select: ['id','name','iblockId'],
    filter: { iblockId: 16, '=name': productVariantName }
  });
  const skuMatches = skuFind.result?.products || [];
  if (skuMatches.length > 0) {
    skuId = skuMatches[0].id;
  } else {
    const skuAdd = await bx.call(this, 'catalog.product.add', {
      fields: {
        iblockId: 16, name: productVariantName, active: 'Y',
        [`property${PROP_PARENT_LINK}`]: { value: parentId }
      }
    });
    skuId = skuAdd.result?.element?.id;
    if (!skuId) throw new Error('SKU create failed: ' + JSON.stringify(skuAdd));
  }

  // Add product row
  const rowResp = await bx.call(this, 'crm.item.productrow.add', {
    fields: {
      ownerType: PRODUCTROW_OWNER_TYPE, ownerId: origItemId,
      productId: skuId, price: unitPrice, quantity: quantity
    }
  });
  const rowId = rowResp.result?.productRow?.id;
  results.push({ line_no: li.line_no, parentId, skuId, rowId, unitPrice, quantity });
}

return [{ json: { spaId: origItemId, reference: data.reference, company_name: data.company_name, line_count: lines.length, lines_added: results } }];

